namespace DeepExtensions.SourceGenerators;

partial class DeepExtensionsGenerator
{
    private void GenerateDeepEqual()
    {
        foreach (var cl in equalClassCollection?.Classes ?? [])
        {
            CreateDeepEqualClassFile(cl);
        }
    }

    private void CreateDeepEqualClassFile(INamedTypeSymbol cl)
    {
        string classNamespace = cl.ContainingNamespace?.ToDisplayString(FormatWithoutNullable) ?? string.Empty;

        StringBuilder sb = new(
            $$"""
            // <auto-generated />

            #nullable enable annotations
            #nullable disable warnings

            // Suppress warnings about [Obsolete] member usage in generated code.
            #pragma warning disable CS0612, CS0618
            
            namespace {{classNamespace}};

            partial class {{cl.Name}} : IDeepEqual<{{cl.Name}}>
            {
                public bool IsDeepEqual({{cl.Name}} other)
                {
                    return 
                        other is not null &&

            """);

        var properties = cl.GetMembers().OfType<IPropertySymbol>();

        foreach (var prop in properties.Where(prop => !prop.GetAttributes().Any(a => a.AttributeClass?.Name == "DeepEqualIgnore")))
        {
            // array data type
            if (prop.Type is IArrayTypeSymbol arrayType)
            {
                if (arrayType.ElementType is INamedTypeSymbol elementType && elementType.IsReferenceType && elementType.SpecialType != SpecialType.System_String)
                {
                    sb.AppendLine($"            {prop.Name}.Length == other.{prop.Name}.Length && {prop.Name}.Zip(other.{prop.Name}, (a, b) => a.IsDeepEqual(b)).All(result => result) &&");
                }
                else
                {
                    sb.AppendLine($"            {prop.Name}.SequenceEqual(other.{prop.Name}) &&");
                }
            }
            // reference data type
            if (prop.Type.IsReferenceType && prop.Type.SpecialType != SpecialType.System_String)
            {
                sb.AppendLine($"            {prop.Name}.IsDeepEqual(other.{prop.Name}) &&");
            }
            // primitive types and string
            else
            {
                sb.AppendLine($"            {prop.Name} == other.{prop.Name} &&");
            }
        }
    
        sb.Append(
            """
                        true;
                }
            }
            """);
        AddSource($"{cl.Name}DeepEqual.g.cs", sb.ToString());
    }
}
